@Service
public class BrandService 
		extends BaseService {
//************************************************************************
// Public Methods
//************************************************************************
	/**
	 * Default Constructor
	 */
    public BrandService(CurrentIdentity identity,
				ApplicationContext applicationContext)  {

		this.identity		= identity;
		this.projector 		= new BrandEntityProjector( applicationContext.getBean(ProjectorRegistry.class),
										applicationContext.getBean(BrandRepository.class) );
		this.validator		= applicationContext.getBean(BrandValidator.class) ;
	}


	/**
	 * Creates the provided command.
	 *
	 * @param		command ${class.getCreateCommandAlias()}
	 * @return		Brand
	 */
		public Brand createBrand( CreateBrandCommand command ) {

		Brand entity = new Brand();

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

            entity.setBrandId( command.getBrandId() );
            entity.setName( command.getName() );
            entity.setDescription( command.getDescription() );
            entity.setWebsite( command.getWebsite() );

		// ------------------------------------------
		// persist a new one
		// ------------------------------------------
		entity = projector.create(entity);

		LOGGER.info( "done creating of Brand {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Update the provided command.
	 * @param		command UpdateBrandCommand
	 * @return		Brand
	 */
	public Brand updateBrand( UpdateBrandCommand command ) {

		Brand entity = new Brand();

		// --------------------------------------
		// validate
		// --------------------------------------
		validator.validate( command );

            entity.setBrandId( command.getBrandId() );
            entity.setName( command.getName() );
            entity.setDescription( command.getDescription() );
            entity.setWebsite( command.getWebsite() );
            entity.setMerchant( command.getMerchant() );
            entity.setProducts( command.getProducts() );

		// ------------------------------------------
		// persist an existing one
		// ------------------------------------------
		entity = projector.update(entity);

		LOGGER.info( "done saving of Brand {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Deletes the associatied value object
	 * @param		command DeleteBrandCommand
	 */
	public void delete( DeleteBrandCommand command ) {
		UUID id = null;

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

		id = command.getBrandId();

		// ------------------------------------------
		// delete the entity
		// ------------------------------------------
		projector.delete(id);

		LOGGER.info( "done deleting of Brand {0} ", id );

	}

	/**
	 * Method to retrieve the Brand via BrandFetchOneSummary
	 * @param 	summary BrandFetchOneSummary
	 * @return 	BrandFetchOneResponse
	 */
	public Brand getBrand( BrandFetchOneSummary summary ) {

		if( summary == null )
			throw new IllegalStateException( "BrandFetchOneSummary arg cannot be null" );

		Brand entity = null;
		UUID id = summary.getBrandId();

		// --------------------------------------
		// validate the fetch one summary
		// --------------------------------------
		validator.validate( summary );

		// --------------------------------------
		// find a Brand using the provided id
		// --------------------------------------
		entity = projector.find( id );

		return entity;
	}


	/**
	 * Method to retrieve a collection of all Brands
	 *
	 * @return 	List<Brand>
	 */
    public List<Brand> getAllBrand() {
		List<Brand> list = projector.findAll( new FindAllBrandQuery() );
		return list;
	}

	/**
	 * assign Merchant on Brand
	 * @param		command AssignMerchantToBrandCommand
	 */
	public void assignMerchant( AssignMerchantToBrandCommand command ) {
		// --------------------------------------
		// best to validate the command now
		// --------------------------------------
		validator.validate( command );

		// --------------------------------------
		// delegate to the projector
		// --------------------------------------
		projector.assignMerchant(command.getBrandId(), command.getAssignment());

	}

	/**
	 * unAssign Merchant on Brand
	 * @param		command UnAssignMerchantFromBrandCommand
	 */
	public void unAssignMerchant( UnAssignMerchantFromBrandCommand command ) {

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

		// --------------------------------------
		// delegate to the projector
		// --------------------------------------
		projector.unAssignMerchant(command.getBrandId());
	}
	

	/**
	 * add Product to Products
	 * @param		command AssignProductsToBrandCommand
	 */
	public void addToProducts( AssignProductsToBrandCommand command ) {

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

		// --------------------------------------
		// delegate to the projector
		// --------------------------------------
		projector.addToProducts(command.getBrandId(), command.getAddTo());
	}

	/**
	 * remove Product from Products
	 * @param		command RemoveProductsFromBrandCommand
	 */
	public void removeFromProducts( RemoveProductsFromBrandCommand command )  {
		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

		// --------------------------------------
		// delegate to the projector
		// --------------------------------------
		projector.removeFromProducts(command.getBrandId(), command.getRemoveFrom());
	}




//************************************************************************
// Attributes
//************************************************************************
	@Autowired
    private final BrandEntityProjector projector;
	private final BrandValidator validator;
	private Brand brand 	= null;
	private CurrentIdentity identity			= null;
	private static final Logger LOGGER 			=  LoggerFactory.getLogger(BrandService.class);
}
